class Solution:
    def makesquare(self, matchsticks: List[int]) -> bool:
        total_length = sum(matchsticks)
        if total_length % 4 != 0:
            return False

        target_side = total_length // 4
        if max(matchsticks) > target_side:
            return False

        n = len(matchsticks)
        dp = [False] * (1 << n)
        dp[0] = True

        for mask in range(1, 1 << n):
            for i in range(n):
                if mask & (1 << i) and dp[mask ^ (1 << i)] and sum(matchsticks[j] for j in range(n) if mask & (1 << j)) <= target_side:
                    dp[mask] = True
                    break

        return dp[(1 << n) - 1]

