class Solution:
    def leafSimilar(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> bool:
        def get_leaves(node):
            if not node:
                return []
            if not node.left and not node.right:
                return [node.val]
            return get_leaves(node.left) + get_leaves(node.right)

        return get_leaves(root1) == get_leaves(root2)

class Solution:
    def numRookCaptures(self, board: List[List[str]]) -> int:
        rows = len(board)
        cols = len(board[0])
        count = 0

        # Find the position of the rook
        for i in range(rows):
            for j in range(cols):
                if board[i][j] == 'R':
                    rook_i, rook_j = i, j
                    break

        # Check horizontal moves
        for col in range(cols):
            if board[rook_i][col] != '.':
                if board[rook_i][col] == 'p' and col < rook_j:
                    count += 1
                    break
                elif board[rook_i][col] == 'B':
                    break

        # Check vertical moves
        for row in range(rows):
            if board[row][rook_j] != '.':
                if board[row][rook_j] == 'p' and row > rook_i:
                    count += 1
                    break
                elif board[row][rook_j] == 'B':
                    break

        return count

class Solution:
    def minimumTime(self, s: str) -> int:
        n = len(s)
        dp = [0] * (n + 1)

        for i in range(1, n + 1):
            if s[i - 1] == '1':
                dp[i] = min(dp[i - 1] + 2, i)
            else:
                dp[i] = dp[i - 1]

        return dp[n]

