class Solution:
    def maximumAlternatingSubarraySum(self, nums: List[int]) -> int:
        if not nums:
            return 0

        max_sum = nums[0]
        current_sum = nums[0]
        alternate_sum = 0

        for i in range(1, len(nums)):
            alternate_sum = current_sum - nums[i] if i % 2 == 1 else current_sum + nums[i]
            current_sum = max(nums[i], alternate_sum)
            max_sum = max(max_sum, current_sum)

        return max_sum

class Solution:
    def tourOfKnight(self, m: int, n: int, r: int, c: int) -> List[List[int]]:
        directions = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
        result = [[-1] * n for _ in range(m)]
        result[r][c] = 0

        def dfs(x, y, step):
            if step == m * n:
                return True
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and result[nx][ny] == -1:
                    result[nx][ny] = step
                    if dfs(nx, ny, step + 1):
                        return True
                    result[nx][ny] = -1
            return False

        dfs(r, c, 1)
        return result

