class Solution:
    def getMinDistSum(self, positions: List[List[int]]) -> float:
        def dist(x, y):
            return sum(math.sqrt((x - px)**2 + (y - py)**2) for px, py in positions)

        # Initial guess for the center
        x, y = sum(p[0] for p in positions) / len(positions), sum(p[1] for p in positions) / len(positions)
        best_dist = dist(x, y)
        step = 1.0

        while step > 1e-6:
            found_better = False
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + step * dx, y + step * dy
                new_dist = dist(nx, ny)
                if new_dist < best_dist:
                    best_dist = new_dist
                    x, y = nx, ny
                    found_better = True
                    break
            if not found_better:
                step /= 2

        return best_dist

class Solution:
    def canArrange(self, arr: List[int], k: int) -> bool:
        counts = collections.Counter(arr)
        odd_counts = 0

        for count in counts.values():
            if count % 2 != 0:
                odd_counts += 1

        if odd_counts > 1:
            return False

        for i in range(1, k):
            if counts[i] != counts[k - i]:
                return False

        return True

class Solution:
    def badSensor(self, sensor1: List[int], sensor2: List[int]) -> int:
        n = len(sensor1)
        for i in range(n):
            if sensor1[i] != sensor2[i]:
                # Check if dropping the current sensor's data results in a different sequence
                if sensor1[:i] + sensor1[i+1:] == sensor2[:i] + sensor2[i+1:]:
                    return 1
                else:
                    return 2
        return -1

