class Solution:
    def minimumMoves(self, grid: List[List[int]]) -> int:
        n = len(grid)
        queue = deque([(0, 0, 1, 0)])  # (x1, y1, x2, y2)
        visited = set((0, 0, 1, 0))
        moves = 0

        while queue:
            for _ in range(len(queue)):
                x1, y1, x2, y2 = queue.popleft()

                if (x1, y1) == (n-1, n-2) and (x2, y2) == (n-1, n-1):
                    return moves

                # Move right
                if y2 + 1 < n and grid[x1][y2 + 1] == 0 and grid[x2][y2 + 1] == 0 and (x1, y2 + 1, x2, y2 + 1) not in visited:
                    visited.add((x1, y2 + 1, x2, y2 + 1))
                    queue.append((x1, y2 + 1, x2, y2 + 1))

                # Move down
                if x2 + 1 < n and grid[x2 + 1][y1] == 0 and grid[x2 + 1][y2] == 0 and (x2 + 1, y1, x2 + 1, y2) not in visited:
                    visited.add((x2 + 1, y1, x2 + 1, y2))
                    queue.append((x2 + 1, y1, x2 + 1, y2))

                # Rotate clockwise
                if x1 == x2 and y2 + 1 < n and grid[x1][y2 + 1] == 0 and grid[x2][y2 + 1] == 0 and (x1, y2, x2, y2 + 1) not in visited:
                    visited.add((x1, y2, x2, y2 + 1))
                    queue.append((x1, y2, x2, y2 + 1))

                # Rotate counterclockwise
                if y1 == y2 and x2 + 1 < n and grid[x2 + 1][y1] == 0 and grid[x2 + 1][y2] == 0 and (x2, y1, x2 + 1, y2) not in visited:
                    visited.add((x2, y1, x2 + 1, y2))
                    queue.append((x2, y1, x2 + 1, y2))

            moves += 1

        return -1

# Definition for a binary tree node.
