class Solution:
    def leafSimilar(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> bool:

        def get_leaf_sequence(node):
            if not node:
                return []
            if not node.left and not node.right:
                return [node.val]
            return get_leaf_sequence(node.left) + get_leaf_sequence(node.right)

        seq1 = get_leaf_sequence(root1)
        seq2 = get_leaf_sequence(root2)

        return seq1 == seq2

from typing import List

class Solution:
    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
        word_set = set(words)

        def can_form(word, count=0):
            if word in word_set and count > 0:
                return True
            for i in range(1, len(word)):
                if word[:i] in word_set and can_form(word[i:], count + 1):
                    return True
            return False

        return [word for word in words if can_form(word)]

