class Solution:
    def closeStrings(self, word1: str, word2: str) -> bool:
        # Create dictionaries to count occurrences of each character in both words
        dict1 = {}
        dict2 = {}

        for char in word1:
            if char in dict1:
                dict1[char] += 1
            else:
                dict1[char] = 1

        for char in word2:
            if char in dict2:
                dict2[char] += 1
            else:
                dict2[char] = 1

        # Check if the lengths of the two dictionaries are different
        if len(dict1) != len(dict2):
            return False

        # Sort the keys of the dictionaries
        sorted_keys1 = sorted(dict1.keys())
        sorted_keys2 = sorted(dict2.keys())

        # Compare the sorted keys
        return sorted_keys1 == sorted_keys2

class Solution:
    def numMagicSquaresInside(self, grid: List[List[int]]) -> int:
        def is_magic_square(subgrid):
            if len(set(subgrid)) != 9 or len(subgrid) != 3:
                return False

            # Check rows and columns
            for i in range(3):
                if sum(subgrid[i]) != 15 or sum([subgrid[j][i] for j in range(3)]) != 15:
                    return False

            # Check diagonals
            if sum([subgrid[i][i] for i in range(3)]) != 15 or sum([subgrid[i][2-i] for i in range(3)]) != 15:
                return False

            return True

        count = 0
        for i in range(len(grid) - 2):
            for j in range(len(grid[0]) - 2):
                subgrid = [grid[x][y] for x in range(i, i+3) for y in range(j, j+3)]
                if is_magic_square(subgrid):
                    count += 1

        return count

class Solution:
    def isValidSerialization(self, preorder: str) -> bool:
        stack = []
        for i in preorder.split(','):
            if i == '#':
                while stack and stack[-1] != '#':
                    stack.pop()
                if not stack or len(stack) > 1:
                    return False
                stack.pop()
            else:
                stack.append(i)
        return len(stack) == 1 and stack[-1] == '#'

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def treeQueries(self, root: Optional[TreeNode], queries: List[int]) -> List[int]:
        depth = {}
        height = {}

        def dfs(node, d):
            if not node:
                return -1
            depth[node.val] = d
            left_height = dfs(node.left, d + 1)
            right_height = dfs(node.right, d + 1)
            height[node.val] = max(left_height, right_height) + 1
            return height[node.val]

        dfs(root, 0)

        level_max_height = defaultdict(lambda: [0, 0])
        def update_level_max_height(node):
            if not node:
                return
            level = depth[node.val]
            if height[node.val] >= level_max_height[level][0]:
                level_max_height[level][1] = level_max_height[level][0]
                level_max_height[level][0] = height[node.val]
            elif height[node.val] > level_max_height[level][1]:
                level_max_height[level][1] = height[node.val]
            update_level_max_height(node.left)
            update_level_max_height(node.right)

        update_level_max_height(root)

        result = []
        for q in queries:
            level = depth[q]
            if height[q] == level_max_height[level][0]:
                result.append(level + level_max_height[level][1])
            else:
                result.append(level + level_max_height[level][0])

        return result

class Solution:
    def leafSimilar(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> bool:
        def get_leaves(node):
            if not node:
                return []
            if not node.left and not node.right:
                return [node.val]
            return get_leaves(node.left) + get_leaves(node.right)

        return get_leaves(root1) == get_leaves(root2)

from typing import List

class Solution:
    def findFarmland(self, land: List[List[int]]) -> List[List[int]]:
        m, n = len(land), len(land[0])
        visited = set()
        result = []

        def dfs(r, c):
            if r < 0 or r >= m or c < 0 or c >= n or land[r][c] == 0 or (r, c) in visited:
                return (r - 1, c - 1)
            visited.add((r, c))
            right = dfs(r, c + 1)
            down = dfs(r + 1, c)
            return (max(right[0], down[0]), max(right[1], down[1]))

        for i in range(m):
            for j in range(n):
                if land[i][j] == 1 and (i, j) not in visited:
                    bottom_right = dfs(i, j)
                    result.append([i, j, bottom_right[0], bottom_right[1]])

        return result

class Solution:
    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        min_length = float('inf')
        left = 0
        current_or = 0

        for right in range(n):
            current_or |= nums[right]

            while current_or >= k:
                min_length = min(min_length, right - left + 1)
                current_or &= ~nums[left]
                left += 1

        return min_length if min_length != float('inf') else -1

class Solution:
    def findTheLongestBalancedSubstring(self, s: str) -> int:
        max_length = 0
        zero_count = 0
        one_count = 0

        for char in s:
            if char == '0':
                if one_count > 0:
                    zero_count = 0
                zero_count += 1
            else:
                one_count += 1
                max_length = max(max_length, min(zero_count, one_count) * 2)

        return max_length

# Definition for a binary tree node.
