#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def isSameTree(self, p: Optional[TreeNode], q: Optional[TreeNode]) -> bool:
        if not p and not q:
            return True
        if not p or not q:
            return False
        return p.val == q.val and self.isSameTree(p.left, q.left) and self.isSameTree(p.right, q.right)

class Solution:
    def wordPatternMatch(self, pattern: str, s: str) -> bool:
        # Dictionary to store the mapping
        mapping = {}

        # Iterate through each character in the pattern
        for i in range(len(pattern)):
            # Check if the current character exists in the mapping
            if pattern[i] not in mapping:
                # If not, create a new mapping with the current character and the rest of the string
                mapping[pattern[i]] = s[i:]
            else:
                # If the character already exists, check if the rest of the string matches the existing mapping
                if mapping[pattern[i]] != s[i:]:
                    # If not, return False
                    return False

        # If all characters match, return True
        return True

class Solution:
    def smallestRangeII(self, nums: List[int], k: int) -> int:
        nums.sort()
        return min(max(nums) - min(nums), nums[-1] - nums[0] - 2*k)

class Solution:
    def majorityElement(self, nums: List[int]) -> List[int]:
        if not nums:
            return []

        # Initialize candidates and their counts
        candidate1, count1 = None, 0
        candidate2, count2 = None, 0

        # First pass: find potential candidates
        for num in nums:
            if count1 == 0:
                candidate1 = num
                count1 = 1
            elif count2 == 0:
                candidate2 = num
                count2 = 1
            elif num == candidate1:
                count1 += 1
            elif num == candidate2:
                count2 += 1
            else:
                count1 -= 1
                count2 -= 1

        # Second pass: verify the candidates
        result = []
        if nums.count(candidate1) > len(nums) // 3:
            result.append(candidate1)
        if nums.count(candidate2) > len(nums) // 3:
            result.append(candidate2)

        return result

class Solution:
    def snakesAndLadders(self, board: List[List[int]]) -> int:
        n = len(board)
        target = n * n

        # Function to get the position on the board from the cell number
        def get_pos(cell):
            row = n - 1 - (cell - 1) // n
            col = (cell - 1) % n
            if row % 2 == 1:
                col = n - 1 - col
            return row, col

        # BFS to find the minimum number of dice rolls
        queue = deque([(1, 0)])  # (current cell, current number of rolls)
        visited = set()

        while queue:
            cell, rolls = queue.popleft()

            if cell == target:
                return rolls

            if cell in visited:
                continue
            visited.add(cell)

            for i in range(1, 7):
                next_cell = cell + i
                if next_cell > target:
                    break

                row, col = get_pos(next_cell)

                if board[row][col] != -1:
                    next_cell = board[row][col]

                queue.append((next_cell, rolls + 1))

        return -1

