class Solution:
    def leafSimilar(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> bool:

        def get_leaves(node):
            if not node:
                return []
            if not node.left and not node.right:
                return [node.val]
            return get_leaves(node.left) + get_leaves(node.right)

        return get_leaves(root1) == get_leaves(root2)

class Solution:
    def checkPossibility(self, nums: List[int]) -> bool:
        # Check if the array is already sorted
        if nums == sorted(nums):
            return True

        # Find the index where the array is not sorted
        for i in range(len(nums) - 1):
            # If the current element is greater than the next element, try to make it smaller
            if nums[i] > nums[i + 1]:
                # Try to make the current element equal to the next element
                if nums[i] == nums[i + 1]:
                    # If it is, remove the next element and check again
                    nums.pop(i + 1)
                    # Check if the array is now sorted
                    if nums == sorted(nums):
                        return True
                else:
                    # If the current element is less than the next element, swap them
                    nums[i], nums[i + 1] = nums[i + 1], nums[i]
                    # Check if the array is now sorted
                    if nums == sorted(nums):
                        return True
                break

        return False

class Solution:
    def smallestNumber(self, pattern: str) -> str:
        n = len(pattern)
        nums = list(range(1, n + 2))

        i = 0
        while i < n:
            if pattern[i] == 'D':
                start = i
                while i < n and pattern[i] == 'D':
                    i += 1
                nums[start:i+1] = reversed(nums[start:i+1])
            else:
                i += 1

        return ''.join(map(str, nums))

