class Solution:
    @lru_cache(None)
    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:
        if desiredTotal == 0:
            return True

        for i in range(1, maxChoosableInteger + 1):
            if not self.canIWin(maxChoosableInteger - i, desiredTotal - i):
                return True

        return False

