import math

class Solution:
    def getMinDistSum(self, positions: List[List[int]]) -> float:
        # Initialize the result variable to store the minimum distance sum
        res = math.inf

        # Iterate over all possible positions for the service center
        for x in range(0, 101):
            for y in range(0, 101):
                # Calculate the total distance from the current position to all customers
                cur_sum = 0
                for pos in positions:
                    cur_sum += math.sqrt((pos[0] - x)**2 + (pos[1] - y)**2)

                # Update the result if the current distance sum is smaller than the previous one
                if cur_sum < res:
                    res = cur_sum

        # Return the minimum distance sum found
        return res

class Solution:
    def longestPalindrome(self, s: str) -> int:
        count = {}
        odd_count = 0

        for char in s:
            if char in count:
                count[char] += 1
            else:
                count[char] = 1

        for value in count.values():
            if value % 2 == 0:
                odd_count += value
            else:
                odd_count += value - 1

        if odd_count > 0:
            odd_count += 1

        return odd_count

class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        def is_valid(x, y):
            return 0 <= x < m and 0 <= y < n

        def dfs(x, y):
            if not is_valid(x, y) or grid[x][y] != 1:
                return 0
            grid[x][y] = 2
            return 1 + sum(dfs(nx, ny) for nx, ny in [(x-1, y), (x+1, y), (x, y-1), (x, y+1)])

        m, n = len(grid), len(grid[0])
        # Step 1: Mark the cells that are hit
        for i, j in hits:
            if grid[i][j] == 1:
                grid[i][j] = 0

        # Step 2: Mark all stable bricks connected to the top row using DFS
        for j in range(n):
            if grid[0][j] == 1:
                dfs(0, j)

        # Step 3: Process each hit in reverse order and count the newly fallen bricks
        result = []
        for i, j in reversed(hits):
            if grid[i][j] == 0:  # If there was no brick originally, no bricks fall
                result.append(0)
                continue
            grid[i][j] = 1  # Restore the brick
            # Check if the restored brick is connected to the top or any stable brick
            if i == 0 or any(is_valid(nx, ny) and grid[nx][ny] == 2 for nx, ny in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]):
                result.append(dfs(i, j) - 1)  # Subtract 1 to exclude the restored brick itself
            else:
                result.append(0)

        return result[::-1]

class Solution:
    def shareCandies(self, candies: List[int], k: int) -> int:
        # Initialize a set to store unique flavors
        unique_flavors = set()

        # Iterate through the list of candies
        for i in range(len(candies)):
            # Add the current candy to the set
            unique_flavors.add(candies[i])

            # If the set size exceeds k, remove the smallest element from the set
            if len(unique_flavors) > k:
                unique_flavors.remove(min(unique_flavors))

        # Return the size of the set, which represents the number of unique flavors
        return len(unique_flavors)

from typing import List
import math

class Solution:
    def getMinDistSum(self, positions: List[List[int]]) -> float:
        def distance_sum(x, y):
            return sum(math.sqrt((x - px) ** 2 + (y - py) ** 2) for px, py in positions)

        step = 1.0
        x = sum(p[0] for p in positions) / len(positions)
        y = sum(p[1] for p in positions) / len(positions)

        while step > 1e-6:
            min_dist = distance_sum(x, y)
            found = False

            for dx, dy in [(-step, 0), (step, 0), (0, -step), (0, step)]:
                nx, ny = x + dx, y + dy
                new_dist = distance_sum(nx, ny)
                if new_dist < min_dist:
                    min_dist = new_dist
                    x, y = nx, ny
                    found = True
                    break

            if not found:
                step /= 10

        return distance_sum(x, y)

from collections import defaultdict

class Solution:
    def maxNumberOfFamilies(self, n: int, reservedSeats: List[List[int]]) -> int:
        # Dictionary to store reserved seats per row
        reserved = defaultdict(set)
        for r, c in reservedSeats:
            reserved[r].add(c)

        # Number of rows with no reserved seats
        ans = 2 * (n - len(reserved))

        # Check each row with reserved seats
        for r in reserved:
            # Initialize flags for each possible group
            left = right = middle = True

            # Check left group (2-5)
            if 2 in reserved[r] or 3 in reserved[r] or 4 in reserved[r] or 5 in reserved[r]:
                left = False

            # Check right group (6-9)
            if 6 in reserved[r] or 7 in reserved[r] or 8 in reserved[r] or 9 in reserved[r]:
                right = False

            # Check middle group (4-7)
            if 4 in reserved[r] or 5 in reserved[r] or 6 in reserved[r] or 7 in reserved[r]:
                middle = False

            # If both left and right groups are available, add 2 to the answer
            if left and right:
                ans += 2
            # If either left or right group is available, add 1 to the answer
            elif left or right:
                ans += 1

        return ans

class Solution:
    def minDeletionSize(self, strs: List[str]) -> int:
