        ans = -1

        # Iterate through each string in the list
        for i in range(len(strs)):
            # Check if the current string is the longest uncommon subsequence
            if len(set(strs[i])) != len(strs[i]):
                ans = max(ans, len(strs[i]))

        # Return the length of the longest uncommon subsequence
        return ans

class Solution:
    def distanceLimitedPathsExist(self, n: int, edgeList: List[List[int]], queries: List[List[int]]) -> List[bool]:
        # Sort edges by their weight
        edgeList.sort(key=lambda x: x[2])

        # Initialize Union-Find data structure
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY

        # Process queries sorted by the limit
        result = [False] * len(queries)
        edge_index = 0
        for i, (p, q, limit) in enumerate(sorted(queries)):
            while edge_index < len(edgeList) and edgeList[edge_index][2] < limit:
                u, v, _ = edgeList[edge_index]
                union(u, v)
                edge_index += 1
            if find(p) == find(q):
                result[i] = True

        return result

class Solution:
    def closedIsland(self, grid: List[List[int]]) -> int:
        def dfs(x, y):
            if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] == 1:
                return False
            grid[x][y] = 1
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                if dfs(x + dx, y + dy):
                    return True
            return False

        count = 0
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 0 and not dfs(i, j):
                    count += 1
        return count

from typing import List

class Solution:
    def checkArray(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        if k == 1:
            return sum(nums) == 0

        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]

        for i in range(n - k + 1):
            if prefix_sum[i + k] - prefix_sum[i] < k:
                return False
            if prefix_sum[i + k] - prefix_sum[i] > k:
                prefix_sum[i + 1] += k - (prefix_sum[i + k] - prefix_sum[i])

        return prefix_sum[-1] == n

class Solution:
    def maxPalindromes(self, s: str, k: int) -> int:
        n = len(s)
        dp = [0] * (n + 1)

        for i in range(n):
            dp[i + 1] = dp[i]

            if i >= k - 1 and s[i - k + 1:i + 1] == s[i - k + 1:i + 1][::-1]:
                dp[i + 1] = max(dp[i + 1], dp[i - k + 1] + 1)

            if i >= k and s[i - k + 2:i + 1] == s[i - k + 2:i + 1][::-1]:
                dp[i + 1] = max(dp[i + 1], dp[i - k + 2] + 1)

        return dp[n]

from collections import Counter

class Solution:
    def longestSubstring(self, s: str, k: int) -> int:
        if not s or len(s) < k:
            return 0

        count = Counter(s)
        for char, freq in count.items():
            if freq < k:
                # Split the string at characters with frequency less than k
                left, right = [], []
                for i, c in enumerate(s):
                    if c == char:
                        if len(left) >= k:
                            right.append(s[i:])
                            break
                        else:
                            left.append(s[i])
                    else:
                        if len(left) >= k:
                            right.append(s[i:])
                            break
                        else:
                            left.append(c)

                # Recursively find the longest substring in both halves
                return max(self.longestSubstring(''.join(left), k), self.longestSubstring(''.join(right), k))

        # If all characters have frequency >= k, return the length of the string
        return len(s)

class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        s1, s2 = sum(nums1), sum(nums2)
        if s1 == s2:
            return 0
        if len(nums1) > len(nums2) * 6 or len(nums2) > len(nums1) * 6:
            return -1
        if s1 < s2:
            nums1, nums2, s1, s2 = nums2, nums1, s2, s1

        diff = [abs(x - y) for x, y in zip(nums1, nums2)]
        diff.sort(reverse=True)
        ops = 0
        while s1 > s2:
            s1 -= diff[ops]
            ops += 1
        return ops

from collections import defaultdict

class Solution:
    def distinctNames(self, ideas: List[str]) -> int:
        prefix_count = defaultdict(set)
        for idea in ideas:
            prefix_count[idea[0]].add(idea[1:])

        result = 0
        for p1 in prefix_count:
            for p2 in prefix_count:
                if p1 < p2:
                    intersection = len(prefix_count[p1] & prefix_count[p2])
                    valid_names = (len(prefix_count[p1]) - intersection) * (len(prefix_count[p2]) - intersection)
                    result += 2 * valid_names

        return result

class Solution:
    def findFarmland(self, land: List[List[int]]) -> List[List[int]]:
        rows, cols = len(land), len(land[0])
        result = []

        for i in range(rows):
            for j in range(cols):
                if land[i][j] == 1:
                    # Found the top-left corner of a farm
                    bottom_right_row, bottom_right_col = i, j

                    # Expand to find the bottom-right corner
                    while bottom_right_row + 1 < rows and land[bottom_right_row + 1][j] == 1:
                        bottom_right_row += 1
                    while bottom_right_col + 1 < cols and land[i][bottom_right_col + 1] == 1:
                        bottom_right_col += 1

                    # Add the farm to the result
                    result.append([i, j, bottom_right_row, bottom_right_col])

                    # Mark the entire farm as visited
                    for r in range(i, bottom_right_row + 1):
                        for c in range(j, bottom_right_col + 1):
                            land[r][c] = 0

        return result

class Solution:
    def countElements(self, arr: List[int]) -> int:
        return sum(1 for num in set(arr) if num + 1 in arr)

from collections import defaultdict, deque
from typing import List

class Solution:
    def sortItems(self, n: int, m: int, group: List[int], beforeItems: List[List[int]]) -> List[int]:
        # Create a new group for each item that belongs to no group
        for u in range(len(group)):
            if group[u] == -1:
                group[u] = m
                m += 1

        # Build directed graphs for items and groups
        graph_items = defaultdict(list)
        indegree_items = [0] * n
        graph_groups = defaultdict(list)
        indegree_groups = [0] * m

        for v in range(n):
            for u in beforeItems[v]:
                graph_items[u].append(v)
                indegree_items[v] += 1
                if group[u] != group[v]:
                    graph_groups[group[u]].append(group[v])
                    indegree_groups[group[v]] += 1

        # Topological sort helper function
        def topologicalSort(graph, indegree):
            visited = []
            stack = deque([node for node in range(len(indegree)) if indegree[node] == 0])

            while stack:
                u = stack.popleft()
                visited.append(u)
                for v in graph[u]:
                    indegree[v] -= 1
                    if indegree[v] == 0:
                        stack.append(v)

            return visited if len(visited) == len(graph) else []

        # Topological sort for groups
        sorted_groups = topologicalSort(graph_groups, indegree_groups)
        if not sorted_groups:
            return []

        # Topological sort for items within each group
        sorted_items = []
        for group_id in sorted_groups:
            items_in_group = [u for u in range(n) if group[u] == group_id]
            sub_graph_items = {u: graph_items[u] for u in items_in_group}
            sub_indegree_items = {u: indegree_items[u] for u in items_in_group}
            sorted_group_items = topologicalSort(sub_graph_items, sub_indegree_items)

            if len(sorted_group_items) != len(items_in_group):
                return []

            sorted_items.extend(sorted_group_items)

        return sorted_items

from typing import List

class Solution:
    def maxProfit(self, prices: List[int], profits: List[int]) -> int:
        n = len(prices)
        left_max_profit = [0] * n
        right_max_profit = [0] * n

        # Calculate the maximum profit from the left up to each index
        current_max_profit = 0
        for i in range(n):
            if profits[i] > current_max_profit:
                current_max_profit = profits[i]
            left_max_profit[i] = current_max_profit

        # Calculate the maximum profit from the right up to each index
        current_max_profit = 0
        for i in range(n-1, -1, -1):
            if profits[i] > current_max_profit:
                current_max_profit = profits[i]
            right_max_profit[i] = current_max_profit

        max_profit = -1

        # Iterate through the middle element
        for j in range(1, n-1):
            if left_max_profit[j-1] > 0 and right_max_profit[j+1] > 0:
                total_profit = left_max_profit[j-1] + profits[j] + right_max_profit[j+1]
                if total_profit > max_profit:
                    max_profit = total_profit

        return max_profit

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def closestNodes(self, root: Optional[TreeNode], queries: List[int]) -> List[List[int]]:
        def inorder_traversal(node):
            if not node:
                return []
            return inorder_traversal(node.left) + [node.val] + inorder_traversal(node.right)

        # Perform inorder traversal to get sorted list of nodes
        sorted_values = inorder_traversal(root)

        def find_closest(value):
            # Find the largest value <= value
            mini = -1
            low, high = 0, len(sorted_values) - 1
            while low <= high:
                mid = (low + high) // 2
                if sorted_values[mid] <= value:
                    mini = sorted_values[mid]
                    low = mid + 1
                else:
                    high = mid - 1

            # Find the smallest value >= value
            maxi = -1
            low, high = 0, len(sorted_values) - 1
            while low <= high:
                mid = (low + high) // 2
                if sorted_values[mid] >= value:
                    maxi = sorted_values[mid]
                    high = mid - 1
                else:
                    low = mid + 1

            return [mini, maxi]

        return [find_closest(query) for query in queries]

from typing import List

class Solution:
    def bestTeamScore(self, scores: List[int], ages: List[int]) -> int:
        # Sort the players based on their ages and then by their scores
        sorted_players = sorted(zip(ages, scores), key=lambda x: (x[0], -x[1]))

        # Initialize the DP array
        dp = [score for score in scores]
        n = len(scores)

        # Fill the DP array
        for i in range(1, n):
            for j in range(i):
                if sorted_players[j][1] <= sorted_players[i][1]:
                    dp[i] = max(dp[i], dp[j] + sorted_players[i][1])

        # Return the maximum score from the DP array
        return max(dp)

class Solution:
    def canConvertString(self, s: str, t: str, k: int) -> bool:
        if len(s) != len(t):
            return False

        shifts = {}

        for i in range(len(s)):
            diff = ord(t[i]) - ord(s[i])
            if diff < 0:
                diff += 26

            if diff not in shifts:
                shifts[diff] = 0

            shifts[diff] += 1

        for shift, count in shifts.items():
            if count > 0 and (shift * count - 1) // 26 >= k:
                return False

        return True

class Solution:
    def isRobotBounded(self, instructions: str) -> bool:
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        x, y = 0, 0
        current_direction = 0

        for instruction in instructions:
            if instruction == 'G':
                x += directions[current_direction][0]
                y += directions[current_direction][1]
            elif instruction == 'L':
                current_direction = (current_direction + 3) % 4
            else:
                current_direction = (current_direction + 1) % 4

        return (x, y) == (0, 0)

from typing import *
class Solution:
    def makesquare(self, matchsticks: List[int]) -> bool:
        total_length = sum(matchsticks)
        if total_length % 4 != 0:
            return False

        target_length = total_length // 4
        sides = [target_length] * 4

        def backtrack(index):
            if index == len(matchsticks):
                return True

            for i in range(4):
                if matchsticks[index] + sides[i] > target_length:
                    continue

                sides[i] += matchsticks[index]
                if backtrack(index + 1):
                    return True
                sides[i] -= matchsticks[index]

            return False

        return backtrack(0)

