from math import gcd

class Solution:
    def subarrayLCM(self, nums: List[int], k: int) -> int:
        res = 0
        for i in range(len(nums)):
            lcm = nums[i]
            for j in range(i + 1, len(nums)):
                lcm = lcm * nums[j] // gcd(lcm, nums[j])
                if lcm == k:
                    res += 1
        return res

