from typing import List

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [1] * n
        self.size = [1] * n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        rootU = self.find(u)
        rootV = self.find(v)
        if rootU != rootV:
            if self.rank[rootU] > self.rank[rootV]:
                self.parent[rootV] = rootU
                self.size[rootU] += self.size[rootV]
            elif self.rank[rootU] < self.rank[rootV]:
                self.parent[rootU] = rootV
                self.size[rootV] += self.size[rootU]
            else:
                self.parent[rootV] = rootU
                self.size[rootU] += self.size[rootV]
                self.rank[rootU] += 1

class Solution:
    def groupStrings(self, words: List[str]) -> List[int]:
        n = len(words)
        uf = UnionFind(n)
        mask_to_index = {}

        for i, word in enumerate(words):
            mask = 0
            for char in word:
                mask |= 1 << (ord(char) - ord('a'))

            if mask in mask_to_index:
                uf.union(i, mask_to_index[mask])
            else:
                mask_to_index[mask] = i

            for j in range(26):
                if mask & (1 << j):
                    new_mask = mask ^ (1 << j)
                    if new_mask in mask_to_index:
                        uf.union(i, mask_to_index[new_mask])
                    for k in range(26):
                        if not (new_mask & (1 << k)):
                            new_new_mask = new_mask | (1 << k)
                            if new_new_mask in mask_to_index:
                                uf.union(i, mask_to_index[new_new_mask])

        max_size = max(uf.size)
        num_groups = sum(1 for i in range(n) if uf.parent[i] == i)
        return [num_groups, max_size]

class Solution:
    def cellsInRange(self, s: str) -> List[str]:
        result = []
        start_col = ord(s[0])
        end_col = ord(s[3])
        start_row = int(s[1])
        end_row = int(s[4])

        for col in range(start_col, end_col + 1):
            for row in range(start_row, end_row + 1):
                result.append(chr(col) + str(row))

        return result

class Solution:
    def sortItems(self, n: int, m: int, group: List[int], beforeItems: List[List[int]]) -> List[int]:
        # Assign unique group IDs for ungrouped items
        for i in range(n):
            if group[i] == -1:
                group[i] = m
                m += 1

        # Build adjacency lists and indegree arrays for items
        item_graph = [[] for _ in range(n)]
        item_indegree = [0] * n
        for i in range(n):
            for j in beforeItems[i]:
                item_graph[j].append(i)
                item_indegree[i] += 1

        # Build adjacency lists and indegree arrays for groups
        group_graph = [[] for _ in range(m)]
        group_indegree = [0] * m
        for i in range(n):
            for j in beforeItems[i]:
                if group[i] != group[j]:
                    group_graph[group[j]].append(group[i])
                    group_indegree[group[i]] += 1

        # Topological sort for items
        item_order = []
        item_queue = deque()
        for i in range(n):
            if item_indegree[i] == 0:
                item_queue.append(i)
        while item_queue:
            item = item_queue.popleft()
            item_order.append(item)
            for neighbor in item_graph[item]:
                item_indegree[neighbor] -= 1
                if item_indegree[neighbor] == 0:
                    item_queue.append(neighbor)

        # If the number of items in the topological order is not n, return an empty list
        if len(item_order) != n:
            return []

        # Topological sort for groups
        group_order = []
        group_queue = deque()
        for i in range(m):
            if group_indegree[i] == 0:
                group_queue.append(i)
        while group_queue:
            group_id = group_queue.popleft()
            group_order.append(group_id)
            for neighbor in group_graph[group_id]:
                group_indegree[neighbor] -= 1
                if group_indegree[neighbor] == 0:
                    group_queue.append(neighbor)

        # If the number of groups in the topological order is not m, return an empty list
        if len(group_order) != m:
            return []

        # Reconstruct the sorted list of items based on group order
        result = []
        for group_id in group_order:
            result.extend(sorted(item_order[i] for i in range(n) if group[i] == group_id))
        return result
